public class Foo {
    private int count;

    void m() {
        int count = 0;
        System.out.println(count);
    }
}

public class Foo {
    private int index;

    void m(int[] values) {
        for (int index = 0; index < values.length; index++) {
            System.out.println(index);
        }
        for (int index : values) {
            System.out.println(index);
        }
    }
}

public enum Level {
    LOW;
    private int weight;

    int m() {
        int weight = 1;
        return weight;
    }
}

record Pair(int a, int b) {
    static int created;
    int m() {
        int created = a + b;
        return created;
    }
}

public class Foo {
    private int count;

    void setCount(int count) {
        this.count = count;
    }

    static class Inner {
        void m() {
            int count = 0;
            System.out.println(count);
        }
    }

    void anonymous() {
        Runnable r = new Runnable() {
            private int calls;

            @Override
            public void run() {
                int count = calls;
                System.out.println(count);
            }
        };
        r.run();
    }
}
